  TextView send=text("➤",22,bg,true);send.setGravity(Gravity.CENTER);send.setBackground(shape(green,25));LinearLayout.LayoutParams sp2=new LinearLayout.LayoutParams(dp(50),dp(50));sp2.setMargins(dp(8),0,0,0);row.addView(send,sp2);send.setOnClickListener(v->{String s=input.getText().toString().trim();input.setText("");handle(s);});bottom.addView(row);
  LinearLayout nav=new LinearLayout(this);String[][] tabs={{"chat","צ׳אט","✧"},{"mine","שלי","▦"},{"knowledge","ידע","◈"},{"settings","הגדרות","⚙"}};for(String[] a:tabs){LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);cell.setGravity(Gravity.CENTER);TextView ic=text(a[2],19,tab.equals(a[0])?green:muted,true);TextView tx=text(a[1],11,tab.equals(a[0])?green:muted,false);cell.addView(ic);cell.addView(tx);cell.setOnClickListener(v->{tab=a[0];renderTab();});nav.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}bottom.addView(nav);root.addView(bottom);renderTab();
