 void renderTab(){body.removeAllViews();if(tab.equals("chat")){title("בוקר טוב, מה נעשה היום?","אפשר לדבר או לכתוב — גם כמה פקודות יחד.");bubble("היי, אני הלן. אני יכולה לעזור בשליטה במכשיר, תזכורות, פתקים, חיפוש וידע מקומי.");quick("הדליקי פנס","הגבירי ווליום","פתחי מצלמה","תזכירי לי בעוד 10 דקות");}
 else if(tab.equals("mine")){title("המרחב שלי","הדברים הקטנים שעושים סדר ביום.");sectionList("פתקים",notes);sectionList("משימות",tasks);sectionList("רשימת קניות",shopping);button("＋ פתק חדש",()->addEntry("notes"));button("＋ משימה",()->addEntry("tasks"));button("＋ לרשימת קניות",()->addEntry("shopping"));button("מעקב שתיית מים  💧",()->{int n=prefs.getInt("water",0)+1;prefs.edit().putInt("water",n).apply();bubble("נרשמו "+n+" כוסות מים היום.");});button("מעקב הוצאות",()->expense());}
 else if(tab.equals("knowledge")){title("ידע אישי אופליין","ייבאי קובץ טקסט ותוכלי לחפש בתוכו גם בלי רשת.");button("ייבוא קובץ ידע",()->importKnowledge());TextView t=text(knowledge.isEmpty()?"עדיין לא יובא קובץ ידע.":("מאגר ידע מוכן · "+knowledge.length()+" תווים"),13,muted,false);body.addView(t);button("חיפוש במאגר",()->{EditText e=new EditText(this);e.setHint("מה לחפש?");new AlertDialog.Builder(this).setTitle("חיפוש ידע").setView(e).setPositiveButton("חיפוש",(d,w)->searchKnowledge(e.getText().toString())).setNegativeButton("ביטול",null).show();});}
 else settings();}
